-- Generated by tools/ingest_photos.py. Safe to run twice. Touches DEMO shops named demo-% only.
-- Run in the Supabase SQL editor AFTER the photo files are deployed to the site (otherwise the app shows the illustration fallback).
begin;
update products set image_url = 'images/photos/apples-800.jpg' where name in ('Apples') and merchant_id in (select id from merchants where slug like 'demo-%' and status = 'DEMO');
